/**
 * How this prototype moves: as iOS does. Pages and sheets ride UIKit's navigation spring (React
 * Navigation's TransitionIOSSpec: stiffness 1000, damping 500, mass 3, which React Native plays
 * critically damped, and so does this); what changes in place, shared layers and bars move on
 * SwiftUI's default spring (response 0.55, no bounce). A link with a motion token of its own keeps it.
 */
const MOTION = {
  page: { type: "spring", stiffness: 1000, damping: 109.54, mass: 3 },
  morph: { type: "spring", stiffness: 130.51, damping: 22.84, mass: 1 },
  change: { type: "spring", stiffness: 130.51, damping: 22.84, mass: 1 },
  bar: { type: "spring", stiffness: 130.51, damping: 22.84, mass: 1 },
} satisfies Record<string, Transition>;

/** When a change of screen looks done, in seconds: what it leaves stays under the new screen until then. */
const SETTLE = { page: 0.407, morph: 0.65 };
const settled = (v?: Via) => (v?.transition ? (v.transition.visualDuration ?? v.transition.duration ?? 0.3) : v?.kind === "smart" ? SETTLE.morph : SETTLE.page);

const MotionCheckIcon = motion.create(CheckIcon);

export type ScreenId = "alMallahMenu" | "basketAlMallah";

/** How a screen was reached: the link's kind, its timing when it has one of its own (else the platform's), and whether it went back. */
export interface Via {
  kind: "smart" | "push" | "dissolve" | "sheet";
  transition?: Transition;
  back?: boolean;
  dir?: "ltr" | "rtl";
}

export interface ScreenProps {
  /** Go to another screen, or back to the one before. */
  go: (to: ScreenId | "back", via: Via) => void;
  /** How this screen was reached (absent for the first one). */
  via?: Via;
  /** Run one of the screen's rules, open or close a part, go back, or go to another screen. */
  act: Act;
  /** The screen's parts that are open (its bars show while theirs is). */
  open: string[];
  /** Where the prototype is: what each screen and the app remember. */
  s: State;
}

/** A screen's part: a sheet, dialog, toast or menu it opens, or a bar it shows. */
export interface PartDef {
  Part: (props: PartProps) => ReactNode;
  kind: "sheet" | "dialog" | "toast" | "menu" | "bar";
  dismiss: ("scrim" | "drag" | "back" | "timer")[];
  /** The frame's width (dialogs, toasts and menus keep it). */
  width: number;
  detent?: "content" | "full";
  ms?: number;
}

export interface PartProps {
  act: Act;
  /** Where the prototype is: what each screen and the app remember. */
  s: State;
}

/** Where a part was opened from, in the device (menus open next to it). */
export interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

export type Action =
  | { do: "open"; part: string }
  | { do: "close"; part?: string }
  | { do: "back" }
  | { do: "go"; to: ScreenId; via: Via }
  /** A rule of the screen's, with the item it runs with (a dish's +). */
  | { do: "run"; rule: string; it?: string }
  /** The screen scrolled to `y`, of the `max` it can. */
  | { do: "scrolled"; y: number; max?: number };

export type TapEvent = { currentTarget: EventTarget };
export type Act = (a: Action, e?: TapEvent) => void;

/** What a press tints with: black over something light, white over something dark (the nearest painted background). */
function inkOver(el: HTMLElement): string {
  for (let n: HTMLElement | null = el; n; n = n.parentElement) {
    const bg = getComputedStyle(n).backgroundColor;
    const c = bg.match(/[\d.]+/g)?.map(Number);
    if (!c || c.length < 3 || (c.length > 3 && c[3] < 0.5)) continue;
    const k = bg.startsWith("color(") ? 255 : 1;
    return (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) * k < 128 ? "#fff" : "#000";
  }
  return "#000";
}

/** The press showing, to end it (a drag that began on it takes over). */
let unpress: (() => void) | null = null;
/** Pointer events a tap target has taken: the innermost one only, as React Native's responder grants a touch to one view. */
const pressed = new WeakSet<Event>();

/** Pressed: from the pointer going down on a tap target until it lets go or slips off. The look is in qalamCSS. */
function press(e: ReactPointerEvent<HTMLElement>) {
  if (e.button !== 0 || pressed.has(e.nativeEvent)) return;
  pressed.add(e.nativeEvent);
  unpress?.();
  const el = e.currentTarget;
  el.style.setProperty("--q-ink", inkOver(el));
  el.dataset.pressed = "";
  const off = () => {
    delete el.dataset.pressed;
    for (const t of ["pointerup", "pointercancel"]) window.removeEventListener(t, off);
    el.removeEventListener("pointerleave", off);
    if (unpress === off) unpress = null;
  };
  unpress = off;
  for (const t of ["pointerup", "pointercancel"]) window.addEventListener(t, off);
  el.addEventListener("pointerleave", off);
}

/** A tap target: click, or Enter / Space when it has focus; pressed while the pointer is down on it, as a control ("dim") or as a row, a card or a button ("fill"). */
const tap = (run: (e: TapEvent) => void, look: "dim" | "fill" = "dim") => ({
  role: "button" as const,
  tabIndex: 0,
  "data-press": look,
  onPointerDown: press,
  onClick: (e: MouseEvent) => run(e),
  onKeyDown: (e: KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      run(e);
    }
  },
});

